import{_ as e,o as t,c as r,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"페르소나","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/personas"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/personas"}],["meta",{"property":"og:title","content":"페르소나"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/personas.md","filePath":"docs/personas.md"}'),d={name:"docs/personas.md"};function c(n,o,l,i,s,p){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="페르소나" tabindex="-1">페르소나 <a class="header-anchor" href="#페르소나" aria-label="Permalink to &quot;페르소나&quot;">​</a></h1><p>세션이 받는 것은 티켓만이 아닙니다. 프롬프트 맨 앞에 <strong>누가 이 일을 하는가</strong>가 먼저 붙고, 그 자리에 들어가는 것이 페르소나입니다. 역할 하나를 적어 둔 마크다운 문서고, 앱에 전용 화면이 있어서 본문만 고치면 됩니다.</p><p>조립 순서는 <code>페르소나 → 프로토콜 → 티켓 지시 → 참조 컨텍스트</code>입니다. 페르소나 바로 뒤에 붙는 프로토콜은 티켓이 고르지 않고 전원이 같은 것을 받습니다. 다음 장에서 다룹니다.</p><h2 id="persona-—-티켓이-정하는-역할" tabindex="-1"><code>persona:</code> — 티켓이 정하는 역할 <a class="header-anchor" href="#persona-—-티켓이-정하는-역할" aria-label="Permalink to &quot;`persona:` — 티켓이 정하는 역할&quot;">​</a></h2><p>티켓의 <code>persona:</code> 값이 곧 프로필 이름입니다. 그 이름의 프로필 본문이 세션 프롬프트 맨 앞에 그대로 실립니다. 워커나 프로젝트가 정하는 것이 아니라 티켓 하나하나가 정합니다. 같은 프로젝트, 같은 워커라도 티켓마다 다른 페르소나로 돕니다.</p><p>프로젝트를 만들면 pm · developer · qa · designer 넷이 같이 섭니다(<a href="/docs/first-ticket">첫 프로젝트 만들기</a>). 출발점일 뿐 고정 목록은 아닙니다. 복사된 순간부터 이 프로젝트의 것이니 화면에서 고치고 지우고 새로 만드시면 됩니다.</p><p>붙이는 기준은 하나입니다. 역할이 판단을 가르는 자리인가를 봅니다. 같은 &quot;버튼이 안 눌린다&quot;도 qa가 받으면 재현 절차와 증거가 남고 developer가 받으면 원인을 찾아 고칩니다. 그렇게 갈리는 티켓에만 이름을 적으세요.</p><p><strong>비워도 됩니다.</strong> 그게 정상 경로입니다. 페르소나 없이 도는 세션은 프로토콜과 티켓 지시만 받고, 경고도 남지 않습니다.</p><p>이름은 적혀 있는데 그 프로필이 없으면 경고만 뜹니다. 페르소나 화면 맨 위에 <code>프로필 파일이 없는 페르소나가 있습니다</code>가 붙고, 그 카드는 접힌 줄에 <code>프로필 없음</code> 배지를 답니다. 엔진은 막지 않습니다. 로그에 <code>WARN</code> 한 줄을 남기고 페르소나 없이 그냥 돌립니다. 티켓이 멈추지는 않되 그 세션은 역할도 권한도 모르는 채로 시작합니다.</p><h2 id="페르소나-화면-—-접힌-카드-목록" tabindex="-1">페르소나 화면 — 접힌 카드 목록 <a class="header-anchor" href="#페르소나-화면-—-접힌-카드-목록" aria-label="Permalink to &quot;페르소나 화면 — 접힌 카드 목록&quot;">​</a></h2><p>왼쪽 내비의 <code>페르소나</code>. 카드는 전부 접혀서 나옵니다. 이 화면의 첫 질문은 &quot;어떤 페르소나가 있나&quot;이고, 편집은 하나를 고른 다음의 일이기 때문입니다.</p><p>접힌 줄 하나가 그 페르소나의 전부를 말해 줍니다. 색 점 · 이름 · 참조하는 티켓 · 스킬 n · n자. 누르면 펼쳐지고, 안에 프로필 원문 입력칸과 <code>저장</code>이 있습니다.</p><ul><li><strong>자수가 접힌 줄에 있는 이유.</strong> 프로필 본문은 그 페르소나의 모든 디스패치 프롬프트에 실립니다. 길이가 곧 매 세션의 비용입니다. 접힌 목록이 &quot;누가 프롬프트를 얼마나 먹는가&quot;를 그대로 보여줍니다.</li><li>여러 개를 동시에 펼쳐도 됩니다. 다른 카드를 연다고 이 카드가 닫히지 않습니다.</li><li>접어도 편집 중인 내용은 살아 있습니다. 저장 버튼은 펼쳐야 보이므로, 저장 안 한 카드는 접힌 줄에 <code>저장 안 됨</code>이 붙습니다.</li><li>프로필이 없는 페르소나는 빈 카드로 뜨고, 저장이 곧 생성입니다. 티켓이 부르는 이름을 그 자리에서 채우시면 됩니다.</li></ul><p>색 점을 누르면 팔레트가 열립니다. 색을 고르는 자리는 이 화면 하나뿐이고, 고른 색은 보드 카드와 테이블, persona 필터, 발행 폼까지 따라다닙니다. 색은 이 컴퓨터에만 저장되고 프로젝트에는 안 들어갑니다. 다른 머신에서 열면 중립 점입니다. 색만으로 뜻을 전하지 않으므로 이름 텍스트는 어디서나 점과 같이 옵니다.</p><h2 id="프로필에-적는-것-—-역할-·-권한-·-판단-기준" tabindex="-1">프로필에 적는 것 — 역할 · 권한 · 판단 기준 <a class="header-anchor" href="#프로필에-적는-것-—-역할-·-권한-·-판단-기준" aria-label="Permalink to &quot;프로필에 적는 것 — 역할 · 권한 · 판단 기준&quot;">​</a></h2><p>무엇을 쓸지는 프로필 바로 앞줄에 이미 적혀 있습니다. 엔진은 세션에게 프로필을 넘기면서 <code>아래 프로필이 당신의 역할·권한·판단 기준이고, 티켓을 수행하는 동안 이 페르소나로 일관되게 행동하세요</code>라고 말합니다. 세션은 그 셋을 찾으면서 읽습니다. 그러니 그 셋을 적으면 됩니다.</p><ul><li><strong>역할은 한 줄입니다.</strong> 기본 넷은 전부 <code>내 일은 …이다</code> 한 문장으로 시작합니다. qa는 &quot;됐다&quot;는 주장을 깨는 것, developer는 티켓 하나를 돌아가는 코드로 바꾸고 그게 돌아간다는 증거를 남기는 것. 이 줄이 나머지를 다 정합니다. 여기가 흐리면 아래를 길게 적어도 방향이 안 잡힙니다.</li><li><strong>권한은 어디까지 손대도 되는지를 그립니다.</strong> qa 프로필은 버그를 찾아도 직접 고치지 말고 티켓을 만들어 넘기라고 적어 뒀습니다. 넘기는 방법까지 같이 적혀 있어야 세션이 경계 앞에서 멈추지 않습니다.</li><li><strong>판단 기준은 갈림길에서 어느 쪽인지를 미리 정해 둡니다.</strong> developer의 <code>첫 번째로 통하는 방법이 정답이다</code>, designer의 <code>라이트/다크 둘 다 정의하지 않은 색은 정의된 게 아니다</code>. 취향이 아니라 판정 문장이라 다음 세션도 같은 자리에서 같은 쪽을 고릅니다.</li><li><strong>하지 않는 것도 적습니다.</strong> qa 프로필의 마지막 절이 그것입니다. 못생긴 건 designer 소관이고 자기는 스펙과 다른 것만 본다고 못박아 뒀습니다. 페르소나가 여럿인 프로젝트에서 이 줄이 서로의 영역을 지킵니다.</li></ul><p>기본 넷은 모두 1인칭으로 쓰여 있습니다. 읽는 쪽이 사람이 아니라 세션이라, <code>내 일은</code>으로 여는 문장이 그 자리에서 세션 자신의 말이 됩니다.</p><p>막히면 기본 넷을 여세요. 프로젝트를 만들면 서는 pm · developer · qa · designer가 각각 20줄에서 90줄 사이입니다. 카드를 펼치면 원문이 그대로 보이니, 새 페르소나는 그중 가까운 하나를 베껴 시작하는 편이 빠릅니다.</p><h2 id="프로필에-적지-않는-것-—-프로토콜과-티켓의-몫" tabindex="-1">프로필에 적지 않는 것 — 프로토콜과 티켓의 몫 <a class="header-anchor" href="#프로필에-적지-않는-것-—-프로토콜과-티켓의-몫" aria-label="Permalink to &quot;프로필에 적지 않는 것 — 프로토콜과 티켓의 몫&quot;">​</a></h2><p>프로필은 그 페르소나의 모든 디스패치에 실리고, 접힌 줄의 <code>n자</code>가 매 세션 내는 값입니다(위 §페르소나 화면). 다 넣고 싶어지더라도, 다른 자리가 있는 문장은 그 자리로 보내세요.</p><ul><li><strong>전원에게 참인 규약은 프로토콜입니다.</strong> 커밋과 보고 형식, 일을 넘기는 법, 막혔을 때 무엇을 남기나. 티켓이 고르지 않고 전원이 같은 것을 받는 자리라, 프로필에 또 적으면 한 프롬프트에 같은 말이 두 번 실립니다. 다음 장 <a href="/docs/protocols">프로토콜</a>이 그 파일을 다룹니다.</li><li><strong>이번 한 번만 참인 지시는 티켓입니다.</strong> &quot;이 파일의 이 절을 이렇게 고쳐 주세요&quot;는 <code>## Goal</code>과 <code>## Done when</code>의 자리입니다(<a href="/docs/ticket-writing">티켓 직접 발행하기</a>). 프로필에 넣으면 그 일이 끝난 뒤에도 모든 세션이 지난 티켓의 지시를 계속 받습니다.</li><li><strong>이 프로젝트에서 해 보고 알아낸 것은 메모리입니다.</strong> 아래 §메모리에서 다룹니다. 사람이 앉아서 채우는 자리가 아니라는 것만 여기서 말해 둡니다.</li></ul><p><strong>프로필과 티켓 지시가 어긋나면 티켓이 이깁니다.</strong> 엔진이 프로필 앞에 그렇게 적어 보냅니다 — 티켓을 따르고, 충돌한 사실을 티켓 본문에 남기라고. 프로필에 예외를 미리 다 적어 두지 않아도 되는 이유입니다.</p><h2 id="스킬-—-이-페르소나가-먼저-집는-도구" tabindex="-1">스킬 — 이 페르소나가 먼저 집는 도구 <a class="header-anchor" href="#스킬-—-이-페르소나가-먼저-집는-도구" aria-label="Permalink to &quot;스킬 — 이 페르소나가 먼저 집는 도구&quot;">​</a></h2><p>카드를 펼치면 프로필 아래에 <code>스킬</code> 절이 있습니다. <code>스킬 추가</code>를 누르면 이 컴퓨터에 설치된 스킬을 검색해 여러 개를 고를 수 있습니다. 고른 목록은 <code>personas/&lt;이름&gt;/skills.md</code>에 저장되고, 그 페르소나의 프롬프트에서 프로필 블록 바로 뒤에 실립니다.</p><p><strong>세션은 설치된 스킬 목록을 이미 갖고 있습니다.</strong> 여기서 넣는 것은 도구가 아니라 지목입니다. &quot;너는 이 일에 이걸 먼저 쓴다&quot;는 뜻입니다.</p><ul><li>접힌 줄의 <code>n자</code>는 프로필과 스킬을 합한 값입니다. 스킬 목록도 같이 실리기 때문입니다.</li><li>0개가 되면 파일을 지웁니다. 빈 파일을 남기지 않습니다.</li><li><code>codex</code> 워커에는 안 실립니다. 그 엔진에 스킬 개념이 없어서, 그대로 실으면 없는 도구를 쓰라는 문장이 갑니다.</li><li>프로필이 없으면 스킬도 안 실립니다. 스킬 블록은 페르소나 프롬프트 안에 사는 것이라, 역할을 모르는 세션에 선택만 얹을 자리가 없습니다.</li><li>다이얼로그의 후보 목록은 이 컴퓨터 기준입니다. 다른 머신에서 고른 스킬은 <code>이 머신에 없음</code>으로 남고 지워지지 않습니다. 고른 결과는 프로젝트에 있어서 프로젝트를 옮기면 따라갑니다.</li></ul><h2 id="메모리-—-세션이-쓰고-사람은-지우는-파일" tabindex="-1">메모리 — 세션이 쓰고 사람은 지우는 파일 <a class="header-anchor" href="#메모리-—-세션이-쓰고-사람은-지우는-파일" aria-label="Permalink to &quot;메모리 — 세션이 쓰고 사람은 지우는 파일&quot;">​</a></h2><p>카드를 펼치면 스킬 절 아래에 <code>메모리</code> 절이 있습니다. 한 줄이 개념 하나입니다. 줄에는 파일명과 본문 첫 줄이 뜨고, 누르면 그 자리에서 전문이 펼쳐집니다. 있는 것은 이게 전부입니다. <code>추가</code>도 <code>편집</code>도 없고 <code>삭제</code>만 있습니다.</p><p>쓰는 쪽이 사람이 아니라 세션이라서 그렇습니다. 티켓을 끝낸 세션은 결과를 적기 직전에 자기 페르소나의 메모리를 들여다봅니다. 이번 일에서 알아낸 것 중 다음 세션이 미리 알았으면 시간을 아꼈을 것이 있으면 한 장 남기고, 없으면 아무것도 하지 않습니다. 프로필이 &quot;너는 누구다&quot;라면 메모리는 &quot;여기서 해 보니 이렇더라&quot;입니다. 앉아서 쓰는 글이 아니니 사람이 채울 칸도 없습니다.</p><p>파일 하나에 개념 하나고 파일명이 곧 개념 이름입니다. 같은 것을 또 배우면 새 파일이 아니라 그 파일을 고쳐 씁니다. 메모리가 개념 수만큼만 자라는 이유입니다.</p><ul><li>접힌 줄에 <code>메모리 n</code>이 붙습니다. 0장이면 그 메타는 안 나오고, 절은 빈 채로 남아 누가 채우는 자리인지만 한 줄로 말합니다.</li><li><code>n자</code>는 이제 셋의 합입니다. 프로필 + 스킬 + 메모리, 셋 다 매 디스패치 프롬프트에 실립니다. 그중 사람 손 없이 자라는 몫은 메모리 하나뿐이라, 늘어나는 비용이 보이는 자리도 여기입니다.</li><li>페르소나 단위이고 프로젝트 안에 있습니다. 워커가 바뀌어도 같은 페르소나면 같은 메모리를 받고, 프로젝트를 옮기면 따라갑니다. 이 컴퓨터에만 남는 값이 아닙니다.</li><li><code>codex</code> 워커에도 실립니다. 스킬과 갈리는 자리입니다. 스킬은 그 엔진에 없는 개념이지만 메모리는 이 프로젝트에서 알아낸 사실이라 엔진을 안 가립니다.</li><li>프로필이 없으면 메모리도 안 실립니다. 스킬과 같은 이유입니다.</li></ul><p><strong>틀린 것은 지우시면 됩니다.</strong> 세션이 남긴 것을 아무도 검사하지 않습니다. 잘못 배운 한 줄도 그대로 실리고, 지울 때까지 그 페르소나의 모든 디스패치를 따라다닙니다. 줄 오른쪽 <code>삭제</code>를 누르면 지울 파일의 경로를 보여 주고 확인을 받습니다. 되돌릴 수는 없습니다. 이 화면에 추가가 없으니 지운 것을 다시 세울 자리도 없습니다. 지울지 말지 판단이 안 서면 본문 끝을 보세요. 세션은 그 개념을 배운 티켓 해시를 <code>출처:</code> 줄에 적게 되어 있습니다. 그 티켓을 열어 보면 어떤 일을 하다 나온 문장인지 되짚을 수 있습니다.</p><p>손으로 고치고 싶으면 큐의 <code>personas/&lt;이름&gt;/memory/</code>에서 파일을 직접 여시면 됩니다. 화면이 그 경로를 막지는 않습니다. 다만 이 절은 세션이 채우는 자리입니다. 직접 쓰는 문장은 프로필에 두세요.</p><h2 id="프롬프트-조립-순서-—-프로필이-실리는-자리" tabindex="-1">프롬프트 조립 순서 — 프로필이 실리는 자리 <a class="header-anchor" href="#프롬프트-조립-순서-—-프로필이-실리는-자리" aria-label="Permalink to &quot;프롬프트 조립 순서 — 프로필이 실리는 자리&quot;">​</a></h2><p>티켓 하나가 디스패치될 때 프롬프트가 한 번 조립됩니다. 들어가는 것은 넷이고 순서가 이렇습니다.</p><ol><li><strong>페르소나.</strong> 프로필 본문, 그 뒤에 스킬 목록, 그 뒤에 메모리 전문. 셋이 붙어서 맨 앞에 섭니다.</li><li><strong>프로토콜.</strong> <code>AGENTS.md</code> 전문이 그대로 들어갑니다. 티켓이 고르지 않고 전원이 같은 것을 받습니다.</li><li><strong>티켓 지시.</strong> <code>&lt;해시&gt; 티켓을 확인해 주세요</code>로 시작하는 한 줄입니다. <strong>티켓 본문은 프롬프트에 없습니다.</strong> 세션이 그 해시로 파일을 직접 엽니다. 그래서 티켓이 아무리 길어져도 프롬프트는 무거워지지 않고, 프로필이 길어지면 무거워집니다.</li><li><strong>참조 컨텍스트.</strong> 워커가 정해 둔 문서 경로 목록이 꼬리에 붙습니다. 파일 내용이 아니라 경로와 한 줄 설명이고, 없는 경로는 건너뜁니다(<a href="/docs/ref-env">워커 환경변수</a>의 <code>TICKET_CONTEXT</code>).</li></ol><p>맨 앞이 프로필이라는 것이 이 순서의 요점입니다. 세션은 프로토콜도 티켓도 그 역할의 눈으로 읽습니다. <code>persona:</code>가 비어 있으면 이 첫 덩이가 통째로 빠집니다. 그 세션에 남는 것은 전원이 같이 받는 규약과 티켓 하나입니다.</p><h2 id="고친-내용이-실리는-시점" tabindex="-1">고친 내용이 실리는 시점 <a class="header-anchor" href="#고친-내용이-실리는-시점" aria-label="Permalink to &quot;고친 내용이 실리는 시점&quot;">​</a></h2><p>프로필도 스킬도 <code>저장</code>을 누르면 파일이 바로 바뀝니다. 메모리를 지워도 그 파일은 그 자리에서 사라집니다. 그런데 지금 도는 세션은 이미 프롬프트를 받은 뒤입니다. 프롬프트는 디스패치 순간에 한 번 조립되고, 그 뒤에 파일이 바뀌어도 돌고 있는 세션은 모릅니다. 바꾼 내용이 실리는 것은 <strong>다음에 디스패치되는 티켓부터</strong>입니다.</p><p>도는 세션에 지금 무언가를 말해야 한다면 그건 다른 자리입니다. <a href="/docs/barge-in">도는 세션에 말 걸기</a>를 보세요.</p><p>다음은 <a href="/docs/protocols">프로토콜</a>입니다.</p>',42)])])}const u=e(d,[["render",c]]);export{h as __pageData,u as default};
